/** Personal realized trades. */
export class TradesResource {
  constructor(private readonly transport: Transport) {}

  /**
   * Realized Trade List
   *
   * Get the user's realized trades (from SELL journal entries) with a sell date between `from` and `to` (inclusive), newest first.
   *
   * Response:
   * - id: Realized trade ID (used by `PATCH /trades/{id}` and `DELETE /trades`)
   * - code: Stock code
   * - broker: Broker code (2 letters)
   * - date: Sell date (WIB (UTC+7) DateTime, e.g. 2026-10-16T00:00:00.000Z = 16 Oct 2026 00:00 WIB; the Z suffix does not mean UTC, do not convert the time zone)
   * - lot: Sold lots (1 lot = 100 shares)
   * - buy_price: Average buy price per share at the time of the sale, incl. buy fee (Rupiah)
   * - sell_price: Sell price per share (Rupiah)
   * - buy_value: Buy value = lot x 100 x buy_price, rounded (Rupiah)
   * - sell_value: Sell value = lot x 100 x sell_price, before sell fee (Rupiah)
   * - net: Net profit/loss = sell_value - sell fee - buy_value, rounded (Rupiah)
   * - percent: Price gain/loss = (sell_price - buy_price) / buy_price x 100, 4 decimals (%)
   * - status: PROFIT, LOSS or BEP based on net
   * - note: User note, null if empty
   *
   * `GET /trades` — cached (`cache.ttl`).
   *
   * @param params Query parameters.
   * @param options Per-request options (e.g. `signal`).
   * @returns TradesListResponse
   */
  list(params: TradesListParams, options?: RequestOptions): Promise<TradesListResponse> {
    return this.transport.request<TradesListResponse>({ method: 'GET', route: '/trades', cache: 'default', query: params }, options);
  }

  /**
   * Delete Realized Trades
   *
   * Delete one or more realized trades by ID (body `{"id": ["<id>", ...]}`). Only the realized-trade records are removed; journal transactions and the portfolio are unchanged.
   *
   * Response:
   * - message: Confirmation message
   *
   * Note: IDs come from the `id` field of `GET /trades`; unknown IDs are ignored.
   *
   * `DELETE /trades` — not cached.
   *
   * @param body Request body: Daftar ID transaksi terealisasi yang akan dihapus.
   * @param options Per-request options (e.g. `signal`).
   * @returns TradesDeleteResponse
   */
  delete(body: DeleteIdsRequest, options?: RequestOptions): Promise<TradesDeleteResponse> {
    return this.transport.request<TradesDeleteResponse>({ method: 'DELETE', route: '/trades', cache: 'none', body }, options);
  }

  /**
   * Realized Trade Summary
   *
   * Get a performance summary of the user's realized trades with a sell date between `from` and `to` (inclusive): profit/loss/BEP counts, totals, win rate, and the best and worst trades.
   *
   * Response:
   * - top_code: Stock codes, most trades first
   * - total_transaction: Number of realized trades in the period
   * - total_profit: Number of PROFIT trades
   * - total_loss: Number of LOSS trades
   * - total_bep: Number of BEP (break-even) trades
   * - total_buy_value: Total buy value (Rupiah)
   * - total_sell_value: Total sell value (Rupiah)
   * - total_net: Total net profit/loss (Rupiah)
   * - win_rate: Share of PROFIT trades (%)
   * - loss_rate: Share of LOSS trades (%)
   * - bep_rate: Share of BEP trades (%)
   * - top_win_value: PROFIT trade with the largest net, contains:
   *   - code: Stock code (empty string if none)
   *   - value: Net value (Rupiah), 0 if none
   * - top_loss_value: LOSS trade with the largest net loss, contains code and value (Rupiah)
   * - top_win_percent: PROFIT trade with the highest percent, contains code and value (%)
   * - top_loss_percent: LOSS trade with the lowest percent, contains code and value (%)
   *
   * Note: When there are no trades in the period, every number is 0, top_code is empty and each top_* is {"code": "", "value": 0}.
   *
   * `GET /trades/summary` — cached (`cache.ttl`).
   *
   * @param params Query parameters.
   * @param options Per-request options (e.g. `signal`).
   * @returns TradesSummaryResponse
   */
  getSummary(params: TradesSummaryParams, options?: RequestOptions): Promise<TradesSummaryResponse> {
    return this.transport.request<TradesSummaryResponse>({ method: 'GET', route: '/trades/summary', cache: 'default', query: params }, options);
  }

  /**
   * Realized Trade Summary Chart
   *
   * Get daily chart data of the user's realized profit/loss with a sell date between `from` and `to` (inclusive), with its running total and the comparison index close on the same day. Only days with realized trades are returned, in ascending date order.
   *
   * Response:
   * - date: Trade day (YYYY-MM-DD, WIB)
   * - net: Net profit/loss on that day, 2 decimals (Rupiah)
   * - cumulative_net: Running total of net since the start of the period, 2 decimals (Rupiah)
   * - close: Comparison index close on that day, 2 decimals; null if no index data
   *
   * Notes:
   * - The `code` parameter is the comparison index code (e.g. COMPOSITE)
   * - When `code` is sent empty (`code=`), a day can appear more than once, one row per index that has data on that day
   *
   * `GET /trades/summary-chart` — cached (`cache.ttl`).
   *
   * @param params Query parameters.
   * @param options Per-request options (e.g. `signal`).
   * @returns TradesSummaryChartResponse
   */
  getSummaryChart(params: TradesSummaryChartParams, options?: RequestOptions): Promise<TradesSummaryChartResponse> {
    return this.transport.request<TradesSummaryChartResponse>({ method: 'GET', route: '/trades/summary-chart', cache: 'default', query: params }, options);
  }

  /**
   * Update Realized Trade Note
   *
   * Update the note of one of the user's realized trades. Body: `{"note": "..."}` (optional, max 150 characters); when `note` is omitted the note is cleared.
   *
   * Response:
   * - message: Confirmation message
   *
   * Note: The ID comes from the `id` field of `GET /trades`. An unknown ID does not produce an error.
   *
   * `PATCH /trades/{id}` — not cached.
   *
   * @param id ID transaksi terealisasi, diambil dari field `id` pada response `GET /trades`. Example: `1`.
   * @param body Request body.
   * @param options Per-request options (e.g. `signal`).
   * @returns TradesUpdateNoteResponse
   */
  updateNote(id: string, body: NoteTradeRequest, options?: RequestOptions): Promise<TradesUpdateNoteResponse> {
    return this.transport.request<TradesUpdateNoteResponse>({ method: 'PATCH', route: '/trades/{id}', cache: 'none', pathParams: { id }, body }, options);
  }

}

/** All API resources. Extended by {@link Invezgo}. */
export class InvezgoResources {
  /** Indonesia stock market data: lists, prices, charts, broker flow, shareholders, fundamentals. */
  readonly analysis: AnalysisResource;
  /** Batch endpoints: fetch many stocks in one request (counted as 1 request). */
  readonly batch: BatchResource;
  /** Search stocks and users. */
  readonly search: SearchResource;
  /** Run stock screeners and manage saved screener presets. */
  readonly screener: ScreenerResource;
  /** API usage and quota monitoring (does not consume quota). */
  readonly usage: UsageResource;
  /** Personal watchlists and watchlist groups. */
  readonly watchlists: WatchlistsResource;
  /** Personal trading journal transactions. */
  readonly journals: JournalsResource;
  /** Personal portfolio built from journal transactions. */
  readonly portfolios: PortfoliosResource;
  /** Live formula alerts. */
  readonly alerts: AlertsResource;
  /** Community posts, comments, likes and votes. */
  readonly posts: PostsResource;
  /** Personal realized trades. */
  readonly trades: TradesResource;

  constructor(transport: Transport) {
    this.analysis = new AnalysisResource(transport);
    this.batch = new BatchResource(transport);
    this.search = new SearchResource(transport);
    this.screener = new ScreenerResource(transport);
    this.usage = new UsageResource(transport);
    this.watchlists = new WatchlistsResource(transport);
    this.journals = new JournalsResource(transport);
    this.portfolios = new PortfoliosResource(transport);
    this.alerts = new AlertsResource(transport);
    this.posts = new PostsResource(transport);
    this.trades = new TradesResource(transport);
  }
}
